import{_ as i,o as l,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Understanding SeaStore through profiling","description":"","frontmatter":{"title":"Understanding SeaStore through profiling","date":"2022-11-14T00:00:00.000Z","updated":"2022-11-15T00:00:00.000Z","tags":["Ceph","性能分析","系统优化","存储系统","Crimson 项目"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Understanding_SeaStore_through_profiling.md","filePath":"posts/2022/Understanding_SeaStore_through_profiling.md","lastUpdated":1780459816000}'),t={name:"posts/2022/Understanding_SeaStore_through_profiling.md"};function o(n,a,s,h,d,u){return l(),e("div",null,[...a[0]||(a[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-通过系统性能分析理解-seastore" tabindex="-1">会议主题：通过系统性能分析理解 SeaStore <a class="header-anchor" href="#会议主题-通过系统性能分析理解-seastore" aria-label="Permalink to &quot;会议主题：通过系统性能分析理解 SeaStore&quot;">​</a></h4><h4 id="主讲人-inching" tabindex="-1">主讲人：Inching <a class="header-anchor" href="#主讲人-inching" aria-label="Permalink to &quot;主讲人：Inching&quot;">​</a></h4><h4 id="背景介绍" tabindex="-1">背景介绍： <a class="header-anchor" href="#背景介绍" aria-label="Permalink to &quot;背景介绍：&quot;">​</a></h4><p>Inching 在 Crimson 项目工作多年，熟悉 Crimson Messenger 及其姊妹项目。Crimson 项目旨在利用多核 CPU 驱动快速 I/O，采用共享内存设计减少跨核心资源共享，设计为租约完成以最小化跨核心跳转和接触开销。项目基于 C-star 框架实现，该框架桥接操作系统和硬件与 Crimson 软件，以实现设计目标。</p><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>Crimson 和 Sister 项目的目标</strong>：有效利用多核 CPU 驱动快速 I/O，使用共享内存设计减少跨核心资源共享，设计为租约完成以最小化跨核心跳转和接触开销。</li><li><strong>C-star 框架</strong>：桥接操作系统和硬件与 Crimson 软件，实现设计目标。</li><li><strong>C-store 目标</strong>：支持多种设备（如 SSD、NVMe），具有不同的性能特征。</li><li><strong>性能分析步骤</strong>： <ul><li>生成工作负载：来自实验室 RPD 客户端或存储 MBD 直接生成。</li><li>收集指标：从 C-star 框架收集，需要在软件层实现。</li><li>数据可视化：理解收集数据的关系和性能趋势。</li></ul></li><li><strong>SeaStore 性能分析</strong>： <ul><li>SeaStore 实现对象存储接口，是 OSD 的本地存储后端。</li><li>支持多层索引、键值存储和偏移量索引。</li><li>数据结构包括逻辑和物理部分，实现逻辑块地址到物理块地址的转换。</li><li>物理层基于日志结构文件系统设计，包括日志记录和清理。</li><li>事务分为读/写事务和空间回收事务，可以并行执行。</li><li>监控指标包括 IOPS、吞吐量、平均请求大小、磁盘利用率、磁盘 I/O、内存使用和缓存命中率。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>性能分析对于诊断问题和预测性能趋势至关重要。</li><li>性能分析分为四个部分：存储背景、性能分析部分、优化示例和关键要点。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续开发和完善性能分析工具和方法。</li><li>根据性能分析结果进行优化和改进。</li><li>保持代码和工具的更新，以适应不断变化的需求。</li></ul><h4 id="关键要点" tabindex="-1">关键要点： <a class="header-anchor" href="#关键要点" aria-label="Permalink to &quot;关键要点：&quot;">​</a></h4><ul><li>性能分析是优化的大部分工作，引入了超过1000个指标和28个PR用于性能分析和工具开发，15个PR用于实际优化。</li><li>优化需要以性能分析为导向，避免不必要的复杂性。</li><li>性能分析迭代需要在所有步骤中进行，包括识别问题、测试场景、重现问题、根本原因分析和验证解决方案。</li><li>性能分析需要在引入的开销和代码复杂性之间取得平衡。</li></ul><h4 id="参考资料" tabindex="-1">参考资料： <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料：&quot;">​</a></h4><ul><li>C-star 框架介绍</li><li>收集指标数据的脚本</li><li>系统代码和日志结构化设计论文链接</li></ul><h4 id="问答环节" tabindex="-1">问答环节： <a class="header-anchor" href="#问答环节" aria-label="Permalink to &quot;问答环节：&quot;">​</a></h4><ul><li><strong>问题</strong>：Crimson OST 和 C-store 能否根据实际工作负载性能特征自动优化？ <ul><li><strong>回答</strong>：目前尚未考虑，但可能是一个好的方向。</li></ul></li><li><strong>问题</strong>：是否可以基于设置的标签追踪客户端 I/O？ <ul><li><strong>回答</strong>：可能，但需要找到连接操作和问题的方法。</li></ul></li></ul><h4 id="结论" tabindex="-1">结论： <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论：&quot;">​</a></h4><p>Inching 详细介绍了 Crimson 项目的性能分析和优化过程，强调了性能分析在系统优化中的重要性，并提出了未来的优化方向和可能的改进措施。</p>',19)])])}const _=i(t,[["render",o]]);export{c as __pageData,_ as default};
